        data: [{ invoice, businessID }],
    } = paymentRequest;
    invoice.invoiceStatus = InvoiceStatus.PAID;
    await invoice.saveToDB();
    WebhookPublishingService.publishEvent({
        topic: WebhookProcessorEventType.Standard,
