/**
 * The default percentage (expressed as a decimal) of the `topUpAmount` which the customer wallet
 * balance needs to fall below before the wallet is automatically refilled back up to the `topUpAmount`.
 */
export const DEFAULT_TOP_UP_THRESHOLD = '0.2';

/**
 * The time frame when an automatic bill should be sent leave empty for no automated billing
 * <br>  • `monthly` - The customer is billed at the beginning of every month for the prior month.
 * <br>  • `annualToDate` - The customer is billed once a year.
 * <br>  • `topUp` - The customer pre-pays credit into their wallet. Usage is deducted from the wallet every hour,
 * and the wallet is automatically refilled back up to the `topUpAmount` whenever the balance drops below
 * `topUpThreshold * topUpAmount`. Only available for `usage-based` offerings.
 * <br><br>
 *
 * Example `"monthly"`
 * @example "monthly"
 */
@IsEnum(ValidBillingCycles)
