/**
 * A `TopUp` offering is a usage based offering which is paid for with prepaid credit held on the customer's wallet.
 *
 * Usage is deducted from the wallet every hour, and the wallet is automatically refilled back up to the
 * `topUpAmount` whenever the balance drops below `topUpThreshold * topUpAmount`. The refill is charged to the
 * customer with an invoice whose payment is stored as credit on the wallet.
 */
export class TopUp extends UsageBased {
    static readonly logger = new Logger(TopUp.name);

    /**
     * The amount, in the currency of the offering, which the wallet is topped up to.
     */
    public topUpAmount: string;

    /**
     * The percentage (expressed as a decimal) of the `topUpAmount` the wallet balance has to drop below before
     * the wallet is refilled. Defaults to `"0.2"`.
     */
    public topUpThreshold: string;

    /**
     * Top up offerings have one billing schedule per offering, instead of one per customer.
     */
    static getTopUpSchedulerId(customerId: string, offeringId: string): string {
        return `topUp-${customerId}-${offeringId}`;
    }

    public getSchedulerID(): string {
        return TopUp.getTopUpSchedulerId(this.customerId, this.offeringId);
    }

    /**
     * The amount the wallet is refilled up to.
     */
    public getTopUpAmount(): number {
        return this.topUpAmount ? parseFloat(this.topUpAmount) : 0;
    }

    /**
     * The balance the wallet has to drop below in order for it to be refilled.
     */
    public getTopUpThresholdAmount(): number {
        const threshold = this.topUpThreshold ? parseFloat(this.topUpThreshold) : parseFloat(DEFAULT_TOP_UP_THRESHOLD);
        return threshold * this.getTopUpAmount();
    }

    async enroll(subject: string, customer?: ReadCustomerResponseData): Promise<void> {
        TopUp.logger.log(
            `Enrolling customer ${this.customerId} in top up offering ${this.offeringName}, top up amount: ${this.topUpAmount}, threshold: ${this.topUpThreshold}`,
        );
        await this.registerBillingSchedule(subject);
        await this.refillWallet({ customer });
    }

    /**
     * Runs every hour for the offering. The usage for the elapsed hour is deducted from the customer's wallet,
     * no usage invoice is generated. Once the usage is deducted the wallet is refilled if the balance dropped
     * below the top up threshold.
     *
     * @returns the ID of the top up invoice, if the wallet needed to be refilled.
     */
    async processBilling(
        startDateOverride?: Date,
        endDateOverride?: Date,
        customer?: ReadCustomerResponseData,
    ): Promise<string> {
        const { startTime, endTime } = Billing.billingCycleToTimeRange(this.billingCycle);
        const startDate = startDateOverride ? startDateOverride : new Date(startTime);
        const endDate = endDateOverride ? endDateOverride : new Date(endTime);
        await this.deductUsageFromWallet({ startDate, endDate, customer });
        return this.refillWallet({ customer });
    }

    /**
     * The total cost of the usage which the customer accrued between the two dates.
     */
    public async calculateUsageTotal({
        startDate,
        endDate,
        customer,
    }: {
        startDate: Date;
        endDate: Date;
        customer?: ReadCustomerResponseData;
    }): Promise<number> {
        const lineItems = await Offering.getLineItemsForUsage({
            startDate,
            endDate,
            customer,
            lineItems: new InvoiceLineItems(),
            negative: false,
            businessID: this.businessID,
            customerId: this.customerId,
            customerService: this.customerService,
            offeringInstance: this,
            dimensions: this.dimensions,
        });
        return parseFloat(lineItems.getTotal().toFixed(2));
    }

    /**
     * Deducts the usage accrued between the two dates from the customer's wallet.
     * The wallet is allowed to go negative, so that usage is never silently dropped.
     */
    public async deductUsageFromWallet({
        startDate,
        endDate,
        customer,
    }: {
        startDate: Date;
        endDate: Date;
        customer?: ReadCustomerResponseData;
    }): Promise<number> {
        const usageTotal = await this.calculateUsageTotal({ startDate, endDate, customer });
        if (!usageTotal || usageTotal <= 0) {
            TopUp.logger.log(
                `No usage to deduct from the wallet of customer ${this.customerId} for offering ${this.offeringName}`,
            );
            return 0;
        }
        const allowNegativeBalance = true;
        const validateCustomer = false;
        await this.getCreditService().create(
            {
                businessID: this.businessID,
                customerId: this.customerId,
                transactionAmount: (usageTotal * -1).toFixed(2),
                timestamp: endDate.toISOString(),
                metadata: {
                    offeringId: this.offeringId,
                    reason: `Usage for ${this.offeringName} between ${startDate.toISOString()} and ${endDate.toISOString()}`,
                },
            },
            validateCustomer,
            allowNegativeBalance,
        );
        TopUp.logger.log(
            `Deducted ${usageTotal} of usage from the wallet of customer ${this.customerId} for offering ${this.offeringName}`,
        );
        return usageTotal;
    }

    /**
     * Refills the customer's wallet back up to the `topUpAmount`, but only when the current balance dropped below
     * `topUpThreshold * topUpAmount`. The exact gap between the current balance and the `topUpAmount` is charged
     * with an invoice, the payment of that invoice is stored as credit on the wallet.
     *
     * @returns the ID of the top up invoice, or `undefined` when no refill was required.
     */
    public async refillWallet({ customer }: { customer?: ReadCustomerResponseData }): Promise<string> {
        const { balance } = await this.getCreditService().findCreditBalance({
            businessID: this.businessID,
            customerId: this.customerId,
        });
        const currentBalance = balance ? parseFloat(balance) : 0;
        const thresholdAmount = this.getTopUpThresholdAmount();
        if (currentBalance >= thresholdAmount) {
            TopUp.logger.log(
                `Wallet balance ${currentBalance} for customer ${this.customerId} is not below the top up threshold ${thresholdAmount}. No top up required.`,
            );
            return undefined;
        }
        const refillAmount = parseFloat((this.getTopUpAmount() - currentBalance).toFixed(2));
        if (refillAmount <= 0) {
            return undefined;
        }
        TopUp.logger.log(
            `Wallet balance ${currentBalance} for customer ${this.customerId} is below the top up threshold ${thresholdAmount}. Charging ${refillAmount} to top up the wallet to ${this.topUpAmount}.`,
        );
        const lineItems = new InvoiceLineItems();
