                    message: 'fake',
                    data: [
                        {
                            dimensionId: dimension.dimensionId,
                            usage: [{ startTime: new Date().toISOString(), endTime: new Date().toISOString(), value }],
                        },
                    ],
                }) as ReadCustomerUsageData,
        );
    };

    const getInstance = (offeringConfig: ReadOfferingResponseData = topUpOffering): TopUp =>
        Offering.getInstance(
            offeringConfig,
            fakeCustomerID,
            fakeBusinessID,
            invoicesService,
            fakeSettings,
            schedulerService,
            customerService,
            undefined,
            undefined,
            creditService,
        ) as TopUp;

    beforeEach(() => {
        //eslint-disable-next-line
        //@ts-ignore
        invoicesService = new InvoicesService();
        //eslint-disable-next-line
        //@ts-ignore
        customerService = new CustomerService();
        //eslint-disable-next-line
        //@ts-ignore
        schedulerService = new SchedulerService();
        //eslint-disable-next-line
        //@ts-ignore
        creditService = new CreditService();
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(invoicesService, 'create').mockImplementation(async () => ({
            invoiceId: 'topUpInvoiceId',
            message: 'created',
        }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(schedulerService, 'create').mockImplementation(async () => ({}));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(schedulerService, 'remove').mockImplementation(async () => ({}));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(creditService, 'create').mockImplementation(async () => ({}));
        jest.spyOn(creditService, 'findCreditBalance').mockImplementation(async () => ({
            balance: '0',
            customerId: fakeCustomerID,
            message: 'found',
        }));
        mockUsage('0');

        topUpOffering = {
            offeringId: fakeOfferingID,
            offeringName: 'payAsYouGo',
            offeringType: OfferingType.usageBased,
            currency: SupportedCurrencies.USD,
            dimensions: [dimension],
            billingCycle: ValidBillingCycles.topUp,
            topUpAmount: '100',
            topUpThreshold: '0.2',
        } as ReadOfferingResponseData;

        customer = {
            customerId: fakeCustomerID,
            customerName: 'fakeCustomerName',
            paymentChannel: paymentChannel.manual,
            businessID: fakeBusinessID,
            currency: SupportedCurrencies.USD,
            email: 'fakeEmail',
        } as ReadCustomerResponseData;
    });

    afterEach(() => {
        jest.clearAllMocks();
        jest.resetAllMocks();
    });

    describe('configuration', () => {
        it('should build a TopUp offering for usage based offerings with a topUp billing cycle', () => {
            const offering = getInstance();
            expect(offering).toBeInstanceOf(TopUp);
            expect(offering).toBeInstanceOf(UsageBased);
            expect(offering.topUpAmount).toEqual('100');
            expect(offering.topUpThreshold).toEqual('0.2');
        });

        it('should default the top up threshold to 0.2', () => {
            const { topUpThreshold, ...withoutThreshold } = topUpOffering;
            const offering = getInstance(withoutThreshold as ReadOfferingResponseData);
            expect(offering.topUpThreshold).toEqual(DEFAULT_TOP_UP_THRESHOLD);
            expect(offering.getTopUpThresholdAmount()).toEqual(20);

            const entity = new OfferingPackageEntity({
                offeringName: 'payAsYouGo',
                offeringId: fakeOfferingID,
                businessID: fakeBusinessID,
                billingCycle: ValidBillingCycles.topUp,
                topUpAmount: '100',
            } as OfferingPackageEntity);
            expect(entity.topUpThreshold).toEqual('0.2');
        });

        it('should persist and read back the top up fields', () => {
            const tag = jest.fn();
            const influxService = {
                getPoint: () => ({ tag, stringField: jest.fn() }),
                //eslint-disable-next-line
                //@ts-ignore
            } as any;
            const entity = new OfferingPackageEntity({
                offeringName: 'payAsYouGo',
                offeringId: fakeOfferingID,
                businessID: fakeBusinessID,
                billingCycle: ValidBillingCycles.topUp,
                topUpAmount: '100',
                topUpThreshold: '0.5',
                dimensionIds: [],
            } as OfferingPackageEntity);
            OfferingPackageEntity.transformer(entity, influxService);
            expect(tag).toHaveBeenCalledWith('billingCycle', ValidBillingCycles.topUp);
            expect(tag).toHaveBeenCalledWith('topUpAmount', '100');
            expect(tag).toHaveBeenCalledWith('topUpThreshold', '0.5');

            const readEntity = OfferingPackageEntity.dbModelToEntity({
                _value: 'payAsYouGo',
                offeringId: fakeOfferingID,
                businessID: fakeBusinessID,
                billingCycle: ValidBillingCycles.topUp,
                topUpAmount: '100',
                topUpThreshold: '0.5',
            });
            expect(readEntity.topUpAmount).toEqual('100');
            expect(readEntity.topUpThreshold).toEqual('0.5');
        });

        it('should schedule top up offerings every hour, once per offering', () => {
            const offering = getInstance();
            expect(offering.getCronRate()).toEqual(SupportedMeasurementFrequencies.everyHour);
            expect(offering.getSchedulerID()).toEqual(TopUp.getTopUpSchedulerId(fakeCustomerID, fakeOfferingID));
            expect(offering.getSchedulerID()).not.toEqual(fakeCustomerID);
        });
    });

    describe('enrollment', () => {
        it('should register the hourly schedule and fill up the wallet', async () => {
            const offering = getInstance();
            await offering.enroll('subject', customer);

            expect(schedulerService.create).toHaveBeenCalledWith(
                expect.objectContaining({
                    schedulerID: TopUp.getTopUpSchedulerId(fakeCustomerID, fakeOfferingID),
                    rate: SupportedMeasurementFrequencies.everyHour,
                    scheduleParameters: {
                        customerId: fakeCustomerID,
                        businessID: fakeBusinessID,
                        offeringId: fakeOfferingID,
                    },
                }),
            );
            expect(invoicesService.create).toHaveBeenCalledWith(
                expect.objectContaining({
                    customerId: fakeCustomerID,
                    businessID: fakeBusinessID,
                    storePaymentAsCredit: true,
                }),
            );
            const [{ items }] = (invoicesService.create as jest.Mock).mock.calls[0];
            expect(items.getTotal()).toEqual(100);
        });

        it('should not top up the wallet when the balance is above the threshold', async () => {
            jest.spyOn(creditService, 'findCreditBalance').mockImplementation(async () => ({
                balance: '20.01',
                customerId: fakeCustomerID,
                message: 'found',
            }));
            const offering = getInstance();
            await offering.enroll('subject', customer);
            expect(schedulerService.create).toHaveBeenCalledTimes(1);
            expect(invoicesService.create).not.toHaveBeenCalled();
        });

        it('should charge exactly the gap between the balance and the top up amount', async () => {
            jest.spyOn(creditService, 'findCreditBalance').mockImplementation(async () => ({
                balance: '19.5',
                customerId: fakeCustomerID,
                message: 'found',
            }));
            const offering = getInstance();
            const invoiceId = await offering.refillWallet({ customer });
            expect(invoiceId).toEqual('topUpInvoiceId');
            const [{ items }] = (invoicesService.create as jest.Mock).mock.calls[0];
            expect(items.getTotal()).toEqual(80.5);
        });
    });

    describe('hourly processing', () => {
        it('should deduct the usage of the elapsed hour from the wallet without creating a usage invoice', async () => {
            jest.spyOn(creditService, 'findCreditBalance').mockImplementation(async () => ({
                balance: '50',
                customerId: fakeCustomerID,
                message: 'found',
            }));
            mockUsage('10');
            const offering = getInstance();
            const invoiceId = await offering.processBilling(undefined, undefined, customer);

            // Usage total is 10 units * $2 = $20
            expect(creditService.create).toHaveBeenCalledWith(
                expect.objectContaining({ transactionAmount: '-20.00', customerId: fakeCustomerID }),
                false,
                true,
            );
            // The balance after the deduction is $30, which is above the $20 threshold
            expect(invoicesService.create).not.toHaveBeenCalled();
            expect(invoiceId).toBeUndefined();

            const [, { startTime, endTime }] = (customerService.findUsageForCustomer as jest.Mock).mock.calls[0];
            expect(new Date(endTime).getTime() - new Date(startTime).getTime()).toEqual(60 * 60 * 1000);
        });

        it('should deduct usage which exceeds the current balance and then refill the wallet', async () => {
            jest.spyOn(creditService, 'findCreditBalance')
                .mockImplementationOnce(async () => ({
                    balance: '5',
                    customerId: fakeCustomerID,
                    message: 'found',
                }))
                .mockImplementation(async () => ({
                    balance: '-15',
                    customerId: fakeCustomerID,
                    message: 'found',
                }));
            mockUsage('10');
            const offering = getInstance();
            const invoiceId = await offering.processBilling(undefined, undefined, customer);

            expect(creditService.create).toHaveBeenCalledWith(
                expect.objectContaining({ transactionAmount: '-20.00' }),
                false,
                true,
            );
            expect(invoiceId).toEqual('topUpInvoiceId');
            const [{ items, storePaymentAsCredit }] = (invoicesService.create as jest.Mock).mock.calls[0];
            // The wallet is refilled with the exact gap between the negative balance and the top up amount
            expect(items.getTotal()).toEqual(115);
            expect(storePaymentAsCredit).toEqual(true);
        });

        it('should not deduct anything when there was no usage', async () => {
            mockUsage('0');
            const offering = getInstance();
            await offering.processBilling(undefined, undefined, customer);
            expect(creditService.create).not.toHaveBeenCalled();
        });
    });

    describe('unenrollment', () => {
        it('should remove the hourly schedule without generating an invoice', async () => {
            mockUsage('1');
            const offering = getInstance();
            await offering.unenroll({ customer });
            expect(creditService.create).toHaveBeenCalledWith(
                expect.objectContaining({ transactionAmount: '-2.00' }),
                false,
                true,
            );
            expect(schedulerService.remove).toHaveBeenCalledWith({
                schedulerID: TopUp.getTopUpSchedulerId(fakeCustomerID, fakeOfferingID),
                businessID: fakeBusinessID,
                isBillingQueue: true,
            });
            expect(invoicesService.create).not.toHaveBeenCalled();
        });
    });
});

